// Generated from src/lib/common.js + src/wf05-replies-logic.js by scripts/build.js.
// Do not edit here: edit the source, run `npm run build`, and re-import the workflow.

// ===== src/lib/common.js =====

// Shared helpers for every workflow's Code nodes.
//
// `npm run build` concatenates this file in front of each workflow module when it
// embeds them into n8n Code nodes (the EXPORT tail is stripped), so everything
// here must run unchanged inside n8n's Code-node sandbox: no `require`, no
// Node-only globals, and plain JavaScript only.

// Two-label public suffixes for the target countries. This is deliberately not
// the full Public Suffix List; anything not listed is treated as a one-label suffix.
const MULTI_LABEL_SUFFIXES = new Set([
  'co.uk', 'org.uk', 'me.uk', 'ltd.uk', 'plc.uk', 'net.uk', 'ac.uk', 'gov.uk', 'sch.uk', 'nhs.uk',
  'com.au', 'net.au', 'org.au', 'id.au', 'asn.au',
  'co.nz', 'org.nz', 'net.nz',
  'ab.ca', 'bc.ca', 'mb.ca', 'nb.ca', 'nl.ca', 'ns.ca', 'nt.ca', 'nu.ca', 'on.ca', 'pe.ca', 'qc.ca', 'sk.ca', 'yk.ca',
]);

// Shared mailbox providers. A suppressed address at one of these must never
// suppress every other user of the provider, and an agency using one gets a warning.
const FREE_MAIL_DOMAINS = new Set([
  'gmail.com', 'googlemail.com', 'hotmail.com', 'hotmail.co.uk', 'outlook.com', 'live.com',
  'live.co.uk', 'msn.com', 'yahoo.com', 'yahoo.co.uk', 'ymail.com', 'icloud.com', 'me.com',
  'aol.com', 'aol.co.uk', 'btinternet.com', 'btopenworld.com', 'sky.com', 'virginmedia.com',
  'talktalk.net', 'ntlworld.com', 'blueyonder.co.uk', 'mail.com', 'gmx.com', 'gmx.co.uk',
  'protonmail.com', 'proton.me', 'zoho.com', 'bigpond.com', 'optusnet.com.au', 'shaw.ca',
  'rogers.com', 'sympatico.ca',
]);

// Lead stages, exactly as in docs/02-mvp-architecture.md §4.
const STAGE = {
  NEW: 'New Lead',
  RESEARCHED: 'Researched',
  QUALIFIED: 'Qualified',
  NEEDS_REVIEW: 'Needs Review',
  DISQUALIFIED: 'Disqualified',
  DRAFT_READY: 'Draft Ready',
  APPROVED: 'Approved',
  CONTACTED: 'Contacted',
  REPLIED: 'Replied',
  MEETING: 'Meeting Opportunity',
  PROPOSAL: 'Proposal Sent',
  WON: 'Won',
  LOST: 'Lost',
  UNSUBSCRIBED: 'Unsubscribed',
};

function text(value) {
  if (value === null || value === undefined) return '';
  return String(value).trim();
}

function isTrue(value) {
  return value === true || text(value).toUpperCase() === 'TRUE';
}

// Returns the lower-cased hostname, or '' if the value is not a usable web address.
// With requireScheme, bare domains like "example.co.uk" are rejected.
function parseHost(value, { requireScheme = false } = {}) {
  const raw = text(value);
  if (!raw || /\s/.test(raw)) return '';
  const match = /^(?:(https?):\/\/)?([^/?#]+)(?:[/?#].*)?$/i.exec(raw);
  if (!match) return '';
  if (!match[1] && requireScheme) return '';
  let authority = match[2];
  if (authority.includes('@')) return '';
  authority = authority.replace(/:\d+$/, '');
  const host = authority.toLowerCase().replace(/\.$/, '');
  if (!host.includes('.')) return '';
  if (/^\d{1,3}(?:\.\d{1,3}){3}$/.test(host)) return '';
  const labels = host.split('.');
  const labelOk = (l) => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(l);
  if (!labels.every(labelOk)) return '';
  if (!/^[a-z]{2,63}$/.test(labels[labels.length - 1])) return '';
  return host;
}

function registrableDomain(host) {
  const h = text(host).toLowerCase().replace(/^www\./, '');
  if (!h) return '';
  const labels = h.split('.');
  if (labels.length <= 2) return h;
  const lastTwo = labels.slice(-2).join('.');
  return MULTI_LABEL_SUFFIXES.has(lastTwo) ? labels.slice(-3).join('.') : lastTwo;
}

const COUNTRY_ALIASES = {
  GB: ['gb', 'uk', 'united kingdom', 'great britain', 'england', 'scotland', 'wales', 'northern ireland'],
  US: ['us', 'usa', 'united states', 'united states of america', 'u.s.', 'u.s.a.'],
  IN: ['in', 'ind', 'india', 'bharat'],
  CA: ['ca', 'canada'],
  AU: ['au', 'australia'],
};

// ISO 3166-1 alpha-2 code, or '' if the value isn't recognisable.
function normaliseCountry(value) {
  const v = text(value).toLowerCase();
  if (!v) return '';
  for (const [code, aliases] of Object.entries(COUNTRY_ALIASES)) if (aliases.includes(v)) return code;
  return /^[a-z]{2}$/.test(v) ? v.toUpperCase() : '';
}

// Splits a configuration cell such as "Reading; Leicester" or "a, b".
function listSetting(value) {
  return text(value).split(/[;,\n]+/).map((x) => x.trim()).filter(Boolean);
}

// Hosting platforms where many unrelated businesses share one registrable domain.
// Subdomain platforms key on the full host; path platforms on host + first path
// segment(s). Social/profile platforms are never fetched for research.
const SUBDOMAIN_PLATFORMS = new Set([
  'wixsite.com', 'weebly.com', 'wordpress.com', 'blogspot.com', 'business.site', 'godaddysites.com',
  'square.site', 'webflow.io', 'netlify.app', 'github.io', 'jimdosite.com', 'mystrikingly.com', 'carrd.co',
]);
const PATH_PLATFORMS = { 'sites.google.com': 2, 'facebook.com': 1, 'instagram.com': 1, 'linkedin.com': 2, 'linktr.ee': 1, 'x.com': 1, 'twitter.com': 1, 'youtube.com': 1, 'yell.com': 2, 'justdial.com': 2 };
const NON_RESEARCHABLE_HOSTS = new Set(['facebook.com', 'instagram.com', 'linkedin.com', 'linktr.ee', 'x.com', 'twitter.com', 'youtube.com', 'yell.com', 'justdial.com', 'tiktok.com', 'wa.me', 'whatsapp.com']);

// Stable dedupe key for a business website: the registrable domain, except on
// shared platforms where unrelated businesses share that domain.
function businessKey(url) {
  const host = parseHost(url);
  if (!host) return '';
  const domain = registrableDomain(host);
  if (SUBDOMAIN_PLATFORMS.has(domain)) return host.replace(/^www\./, '');
  if (PATH_PLATFORMS[domain] || PATH_PLATFORMS[host.replace(/^www\./, '')]) {
    const depth = PATH_PLATFORMS[domain] || PATH_PLATFORMS[host.replace(/^www\./, '')];
    const path = (/^(?:https?:\/\/)?[^/?#]+(\/[^?#]*)?/i.exec(text(url))[1] || '').split('/').filter(Boolean).slice(0, depth);
    return [host.replace(/^www\./, ''), ...path.map((p) => p.toLowerCase())].join('/');
  }
  return domain;
}

// True for profile/directory platforms that must not be fetched or treated as
// the business's own website.
function isNonResearchableSite(url) {
  const host = parseHost(url).replace(/^www\./, '');
  return Boolean(host) && (NON_RESEARCHABLE_HOSTS.has(host) || NON_RESEARCHABLE_HOSTS.has(registrableDomain(host)));
}

function normaliseEmail(value) {
  return text(value).replace(/^mailto:/i, '').replace(/\?.*$/, '').trim().toLowerCase();
}

function isValidEmail(email) {
  if (!email || email.length > 254) return false;
  const at = email.lastIndexOf('@');
  if (at < 1 || at !== email.indexOf('@')) return false;
  const local = email.slice(0, at);
  const domain = email.slice(at + 1);
  if (local.length > 64) return false;
  if (!/^[a-z0-9!#$%&'*+/=?^_`{|}~-]+(?:\.[a-z0-9!#$%&'*+/=?^_`{|}~-]+)*$/.test(local)) return false;
  return domain !== '' && parseHost(domain) === domain;
}

function emailDomain(email) {
  return email.slice(email.indexOf('@') + 1);
}

// Google Sheets may return a date cell as a serial day number (days since 1899-12-30).
function normaliseDate(value) {
  if (typeof value === 'number' && value > 20000 && value < 80000) {
    return new Date(Date.UTC(1899, 11, 30) + value * 86400000).toISOString();
  }
  const raw = text(value);
  if (!raw) return '';
  return Number.isNaN(Date.parse(raw)) ? null : raw;
}

// Milliseconds since epoch for a timestamp cell, or NaN.
function timeOf(value) {
  const d = normaliseDate(value);
  return d ? Date.parse(d) : NaN;
}

function parseSettings(settingsRows) {
  const settings = {};
  for (const row of settingsRows || []) {
    const key = text(row && row.key);
    if (key) settings[key] = row.value;
  }
  return settings;
}

// Fails closed: without a valid, active niche the calling workflow is aborted.
function resolveActiveNiche(settings, nichesRows, action = 'import') {
  const nicheId = text(settings.ACTIVE_NICHE);
  if (!nicheId) throw new Error(`Settings.ACTIVE_NICHE is missing or blank; ${action} aborted.`);
  const niche = (nichesRows || []).find((n) => n && text(n.niche_id) === nicheId);
  if (!niche) throw new Error(`ACTIVE_NICHE "${nicheId}" has no row in the Niches tab; ${action} aborted.`);
  if (!isTrue(niche.active)) throw new Error(`Niche "${nicheId}" is not active (Niches.active must be TRUE); ${action} aborted.`);
  if (!text(niche.country)) throw new Error(`Niche "${nicheId}" has no country; ${action} aborted.`);
  return { niche_id: nicheId, country: text(niche.country), row: niche };
}

// Suppression applies to the exact address and to the company domain, except
// that shared mail providers are never suppressed at domain level (§3.4).
function buildSuppressionIndex(suppressionRows) {
  const suppressedEmails = new Set();
  const suppressedDomains = new Set();
  for (const row of suppressionRows || []) {
    if (!row) continue;
    const email = normaliseEmail(row.email);
    if (email) {
      suppressedEmails.add(email);
      if (isValidEmail(email)) {
        const d = registrableDomain(emailDomain(email));
        if (!FREE_MAIL_DOMAINS.has(d)) suppressedDomains.add(d);
      }
    }
    const domain = registrableDomain(parseHost(row.domain));
    if (domain && !FREE_MAIL_DOMAINS.has(domain)) suppressedDomains.add(domain);
  }
  return { suppressedEmails, suppressedDomains };
}

// Returns '' when the contact may be used, otherwise a reason string.
function suppressionReason(index, email, leadId) {
  const e = normaliseEmail(email);
  if (e && index.suppressedEmails.has(e)) return 'contact_email is on the Suppression list';
  const lead = text(leadId).toLowerCase();
  const mailDomain = e && e.includes('@') ? registrableDomain(emailDomain(e)) : '';
  if ((lead && index.suppressedDomains.has(lead)) || (mailDomain && !FREE_MAIL_DOMAINS.has(mailDomain) && index.suppressedDomains.has(mailDomain))) {
    return 'domain is on the Suppression list';
  }
  return '';
}

// Rows from a Sheets read, minus the empty {} item n8n emits for an empty tab.
function realRows(rows) {
  return (rows || []).filter((r) => r && Object.keys(r).length > 0);
}

// Calendar parts of an instant in an IANA time zone (Intl is available both in
// Node and in the n8n Code-node sandbox; Luxon is not needed).
function zonedParts(ms, timeZone) {
  const fmt = new Intl.DateTimeFormat('en-GB', {
    timeZone, weekday: 'short', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
  });
  const parts = Object.fromEntries(fmt.formatToParts(new Date(ms)).map((p) => [p.type, p.value]));
  return {
    weekday: parts.weekday,
    date: `${parts.year}-${parts.month}-${parts.day}`,
    minutes: Number(parts.hour) * 60 + Number(parts.minute),
  };
}

function isValidTimeZone(timeZone) {
  try {
    new Intl.DateTimeFormat('en-GB', { timeZone: text(timeZone) || 'invalid/zone' });
    return true;
  } catch (e) {
    return false;
  }
}

function clip(value, max) {
  const s = text(value);
  return s.length > max ? `${s.slice(0, max - 1)}…` : s;
}

// Evidence is stored in Leads.evidence as one line per item:  "quote" — url [signal]
function formatEvidence(items) {
  return (items || [])
    .map((e) => `"${text(e.quote).replace(/"/g, "'")}" — ${text(e.url)}${text(e.signal) ? ` [${text(e.signal)}]` : ''}`)
    .join('\n');
}

function parseEvidence(value) {
  const out = [];
  for (const line of text(value).split('\n')) {
    const m = /^"(.*)" — (\S+)(?: \[(.*)\])?$/.exec(line.trim());
    if (m) out.push({ quote: m[1], url: m[2], signal: m[3] || '' });
  }
  return out;
}

// Whole numbers 0..max written as digits (Sheets may return them as numbers).
function parseIntSetting(value, min, max) {
  const s = text(value);
  if (!/^\d+$/.test(s)) return NaN;
  const n = Number(s);
  return n >= min && n <= max ? n : NaN;
}

// Index of the input item an n8n output item came from (HTTP Request and Gmail
// nodes replace an item's JSON, so later Code nodes recover context this way).
function pairedIndex(item, fallback) {
  const p = item && (Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem);
  return p && typeof p.item === 'number' ? p.item : fallback;
}

// ===== src/wf05-replies-logic.js =====

// WF05 Replies & Bounces: pure logic (docs/02-mvp-architecture.md §6).
//
// Embedded after common.js into the "Classify Messages" Code node of
// workflows/WF05-replies-bounces.json. IMPORTS and the EXPORT tail are stripped.
//
// Matches recent inbox messages to real (non-test) sends via the Gmail thread ID
// or, for bounces, the failed recipient address. Opt-outs and bounces are decided
// by keyword rules only (no AI reads private replies) and are suppressed
// immediately. Everything else is marked for a human to read.



const WF05_COLUMNS = ['lead_id', 'stage', 'reply_status', 'reply_received_at', 'reply_category', 'next_action', 'last_updated'];

const REPLY_STATUS = { REPLIED: 'replied', BOUNCED: 'bounced', UNSUBSCRIBED: 'unsubscribed', AUTO: 'auto_reply' };
const AUTO_CATEGORIES = new Set(['', 'needs_review', 'auto_reply', 'bounce', 'unsubscribe']);
// Stages a human has moved the lead into; WF05 never overwrites them.
const SALES_STAGES = new Set([STAGE.MEETING, STAGE.PROPOSAL, STAGE.WON, STAGE.LOST]);

const OPT_OUT = /\b(unsubscribe|remove me|take me off|opt[ -]?out|stop (?:emailing|contacting|sending|messaging)|do not (?:contact|email|e-mail)|don'?t (?:contact|email|e-mail)|no more (?:emails|e-mails|messages)|not interested,? (?:please )?(?:remove|stop))\b/i;
const AUTO_REPLY_SUBJECT = /\b(automatic reply|auto(?:matic)?[- ]?reply|out of (?:the )?office|away from (?:the|my) office|on (?:annual )?leave|autoreply|abwesenheit)\b/i;
const BOUNCE_FROM = /(mailer-daemon|postmaster|mail delivery (?:subsystem|system))/i;
const BOUNCE_SUBJECT = /(delivery status notification|undeliverable|undelivered mail|delivery (?:has )?failed|failure notice|returned mail|mail delivery failed|could not be delivered)/i;

function headerValue(message, name) {
  const h = message.headers || {};
  const raw = h[name] || h[name.toLowerCase()];
  if (!raw) return '';
  const line = Array.isArray(raw) ? raw.join(', ') : String(raw);
  return line.replace(new RegExp(`^${name}\\s*:\\s*`, 'i'), '').trim();
}

function fromAddress(message) {
  const f = message.from;
  if (f && Array.isArray(f.value) && f.value[0]) return normaliseEmail(f.value[0].address);
  const m = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i.exec(typeof f === 'string' ? f : (f && f.text) || '');
  return m ? normaliseEmail(m[0]) : '';
}

// Only the newly written part of a reply: quoted history (which contains our own
// footer and its "unsubscribe" wording) must never trigger an opt-out.
function newContent(body) {
  const lines = String(body || '').replace(/\r\n/g, '\n').split('\n');
  const out = [];
  for (const line of lines) {
    const l = line.trim();
    if (/^>/.test(l)) break;
    if (/^On .{4,200}wrote:?$/i.test(l) || /^-{2,}\s*Original Message\s*-{2,}$/i.test(l) || /^_{10,}$/.test(l)) break;
    if (/^(From|Sent|De|Von):\s/i.test(l) && out.length) break;
    if (/^(?:Le|Am) .{4,200}(?:a écrit|schrieb)\s*:?$/i.test(l)) break;
    out.push(line);
  }
  return out.join('\n').trim();
}

function classifyMessage(message, sentEmails) {
  const subject = text(message.subject);
  const from = fromAddress(message);
  if (BOUNCE_FROM.test(from) || BOUNCE_FROM.test(text(message.from && message.from.text)) || BOUNCE_SUBJECT.test(subject)) {
    const failed = [];
    const header = headerValue(message, 'X-Failed-Recipients');
    for (const e of header.split(/[,\s]+/)) if (isValidEmail(normaliseEmail(e))) failed.push(normaliseEmail(e));
    if (!failed.length) {
      for (const m of String(message.text || '').matchAll(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/gi)) {
        const e = normaliseEmail(m[0]);
        if (sentEmails.has(e)) failed.push(e);
      }
    }
    return { kind: 'bounce', failed: [...new Set(failed)] };
  }
  const autoSubmitted = headerValue(message, 'Auto-Submitted').toLowerCase();
  if ((autoSubmitted && autoSubmitted !== 'no') || headerValue(message, 'X-Autoreply') || headerValue(message, 'X-Autorespond') || AUTO_REPLY_SUBJECT.test(subject)) {
    return { kind: 'auto_reply' };
  }
  const fresh = newContent(message.text);
  if (OPT_OUT.test(fresh) || /\bunsubscribe\b/i.test(subject.replace(/^\s*(re|fw|fwd)\s*:\s*/i, ''))) return { kind: 'opt_out', from };
  return { kind: 'reply', from };
}

function messageTime(message) {
  const t = timeOf(message.date);
  if (Number.isFinite(t)) return t;
  const internal = Number(message.internalDate);
  return Number.isFinite(internal) && internal > 0 ? internal : NaN;
}

function processMessages({ leadsRows, sendLogRows, suppressionRows, messages, now }) {
  const ts = text(now) || new Date().toISOString();
  const leads = realRows(leadsRows);
  const leadById = new Map(leads.map((l) => [text(l.lead_id), l]));
  const byThread = new Map();
  const byEmail = new Map();
  for (const row of realRows(sendLogRows)) {
    if (text(row.status) !== 'sent') continue; // test sends are never matched
    if (text(row.gmail_thread_id)) byThread.set(text(row.gmail_thread_id), text(row.lead_id));
    if (text(row.to_email)) byEmail.set(normaliseEmail(row.to_email), text(row.lead_id));
  }
  const sentEmails = new Set(byEmail.keys());
  const existing = buildSuppressionIndex(realRows(suppressionRows));
  const alreadySuppressed = new Set(existing.suppressedEmails);

  const state = new Map(); // lead_id -> working copy of WF05 columns
  const suppressions = [];
  const summary = { messages: 0, matched: 0, unmatched: 0, alreadyProcessed: 0, replies: 0, optOuts: 0, bounces: 0, autoReplies: 0 };

  const working = (leadId) => {
    if (!state.has(leadId)) {
      const lead = leadById.get(leadId);
      const row = {};
      for (const c of WF05_COLUMNS) row[c] = lead[c] === undefined || lead[c] === null ? '' : lead[c];
      state.set(leadId, { row, changed: false, watermark: timeOf(lead.reply_received_at) });
    }
    return state.get(leadId);
  };
  const suppress = (email, domain, reason, source) => {
    const e = normaliseEmail(email);
    if (!isValidEmail(e) || alreadySuppressed.has(e)) return;
    alreadySuppressed.add(e);
    suppressions.push({ email: e, domain: text(domain), reason, source, added_at: ts });
  };

  const sorted = realRows(messages)
    .map((m) => ({ m, t: messageTime(m) }))
    .sort((a, b) => (Number.isFinite(a.t) ? a.t : 0) - (Number.isFinite(b.t) ? b.t : 0));

  for (const { m, t } of sorted) {
    summary.messages += 1;
    const c = classifyMessage(m, sentEmails);
    let leadId = byThread.get(text(m.threadId)) || '';
    if (!leadId && c.kind === 'bounce') leadId = c.failed.map((e) => byEmail.get(e)).find(Boolean) || '';
    if (!leadId || !leadById.has(leadId)) { summary.unmatched += 1; continue; }
    summary.matched += 1;
    const w = working(leadId);
    // Already handled in an earlier run (idempotency watermark).
    if (Number.isFinite(t) && Number.isFinite(w.watermark) && t <= w.watermark) { summary.alreadyProcessed += 1; continue; }
    const when = Number.isFinite(t) ? new Date(t).toISOString() : ts;
    const lead = leadById.get(leadId);
    const r = w.row;
    const companyDomain = text(lead.lead_id);
    const source = `gmail:${text(m.id)}`;

    if (c.kind === 'bounce') {
      summary.bounces += 1;
      const failed = c.failed.length ? c.failed : [normaliseEmail(lead.contact_email)];
      failed.forEach((e) => suppress(e, '', 'bounce', source));
      if (r.reply_status !== REPLY_STATUS.UNSUBSCRIBED) {
        r.reply_status = REPLY_STATUS.BOUNCED;
        r.reply_category = 'bounce';
        r.next_action = 'Email bounced: check the address before any further contact';
      }
    } else if (c.kind === 'opt_out') {
      summary.optOuts += 1;
      suppress(lead.contact_email, companyDomain, 'unsubscribe', source);
      if (c.from && c.from !== normaliseEmail(lead.contact_email)) {
        const d = registrableDomain(emailDomain(c.from));
        suppress(c.from, FREE_MAIL_DOMAINS.has(d) ? '' : d, 'unsubscribe', source);
      }
      r.reply_status = REPLY_STATUS.UNSUBSCRIBED;
      r.reply_category = 'unsubscribe';
      if (SALES_STAGES.has(text(r.stage))) {
        r.next_action = 'Opt-out received: stop all marketing; review the open opportunity by hand';
      } else {
        r.stage = STAGE.UNSUBSCRIBED;
        r.next_action = 'Opt-out received: do not contact again';
      }
    } else if (c.kind === 'auto_reply') {
      summary.autoReplies += 1;
      // An auto-reply never overrides a real reply, bounce or opt-out.
      if (!text(r.reply_status)) {
        r.reply_status = REPLY_STATUS.AUTO;
        r.reply_category = 'auto_reply';
        r.next_action = 'Auto-reply received: no action needed';
      }
    } else {
      summary.replies += 1;
      if (r.reply_status !== REPLY_STATUS.UNSUBSCRIBED) {
        r.reply_status = REPLY_STATUS.REPLIED;
        if (AUTO_CATEGORIES.has(text(r.reply_category))) r.reply_category = 'needs_review';
        r.next_action = 'Read the reply in Gmail, then set reply_category (positive / neutral / negative) and the next stage';
        if (text(r.stage) === STAGE.CONTACTED) r.stage = STAGE.REPLIED;
      }
    }
    r.reply_received_at = when;
    r.last_updated = ts;
    w.watermark = Number.isFinite(t) ? t : w.watermark;
    w.changed = true;
  }

  const leadUpdates = [...state.values()].filter((w) => w.changed).map((w) => ({ ...w.row, next_action: clip(w.row.next_action, 300) }));
  return { leadUpdates, suppressions, summary };
}

// ---- n8n glue ----
const rowsFrom = (nodeName) =>
  $(nodeName).all().map((item) => item.json).filter((row) => row && Object.keys(row).length > 0);
const result = processMessages({
  leadsRows: rowsFrom('Read Leads'),
  sendLogRows: rowsFrom('Read Send_Log'),
  suppressionRows: rowsFrom('Read Suppression'),
  messages: rowsFrom('Get Recent Messages'),
  now: new Date().toISOString(),
});
